  [13795] = { "Fire trapを設置します。最初に近づいた敵を燃やし、$D1かけて$N1のFireダメージを与えます。罠は$D2の間存在します。同時に設置できるFire trapは1つだけです。", nil, 0x2a66629e, nil, "um" },
